[{"order":1,"type":"heading","text":"Writing Reusable Composables (Best Practices & Cleanups)"},{"order":2,"type":"paragraph","text":"Vue 3 Composition API introduced Composables, a mechanism for encapsulating and reusing stateful logic. Writing clean, scalable, and maintainable composables requires strict adherence to naming conventions, proper handling of reactive states, and diligent resource cleanup."},{"order":3,"type":"subheading","text":"1. Naming and File Structure"},{"order":4,"type":"bullet_point","text":"Always prefix your composable function name with 'use' (e.g., useWindowSize, useFetch)."},{"order":5,"type":"bullet_point","text":"Keep files grouped logically in a 'composables/' directory at the root of your source folder."},{"order":6,"type":"subheading","text":"2. Accepting Reactive Arguments"},{"order":7,"type":"paragraph","text":"To make composables flexible, accept arguments that can be either plain values, refs, or getters. Use Vue's 'toValue()' utility to normalize these inputs safely."},{"order":8,"type":"code","text":"import { ref, watchEffect, toValue, MaybeRefOrGetter } from 'vue';

export function useIdFetch(url: MaybeRefOrGetter<string>) {
  const data = ref(null);
  const error = ref(null);

  watchEffect(async () => {
    // toValue normalizes refs, getters, and raw values
    const resolvedUrl = toValue(url);
    try {
      const response = await fetch(resolvedUrl);
      data.value = await response.json();
    } catch (err) {
      error.value = err;
    }
  });

  return { data, error };
}"},{"order":9,"type":"subheading","text":"3. Proper Resource Cleanup"},{"order":10,"type":"paragraph","text":"Composables that set up global side effects (such as event listeners, timers, or WebSocket connections) must clean them up when the component unmounts. Always leverage 'onUnmounted()' or rely on current scope automatic disposal."},{"order":11,"type":"code","text":"import { ref, onMounted, onUnmounted } from 'vue';

export function useEventListener(target: EventTarget, event: string, callback: EventListener) {
  onMounted(() => {
    target.addEventListener(event, callback);
  });

  onUnmounted(() => {
    target.removeEventListener(event, callback);
  });
}"},{"order":12,"type":"subheading","text":"4. Returning State Safely"},{"order":13,"type":"bullet_point","text":"Return reactive state using 'readonly()' if consumers should not modify the state directly inside the composable."},{"order":14,"type":"bullet_point","text":"Return plain objects, not reactive arrays, to prevent destructuring pitfalls."},{"order":15,"type":"code","text":"import { ref, readonly } from 'vue';

export function useCounter() {
  const count = ref(0);
  const increment = () => count.value++;

  return {
    count: readonly(count),
    increment
  };
}"}]
